alter table public.timeline_daw_normalization_support_cases add column if not exists priority text not null default 'normal' check(priority in('critical','high','normal','low')),add column if not exists due_at timestamptz,add column if not exists assigned_to text,add column if not exists bundle_cleaned_at timestamptz;update public.timeline_daw_normalization_support_cases set due_at=created_at+interval '72 hours' where due_at is null;alter table public.timeline_daw_normalization_support_cases alter column due_at set not null;create index if not exists timeline_daw_normalization_support_triage on public.timeline_daw_normalization_support_cases(owner_id,session_id,state,priority,due_at);alter table public.timeline_daw_normalization_support_case_history drop constraint if exists timeline_daw_normalization_support_case_history_event_check;alter table public.timeline_daw_normalization_support_case_history add constraint timeline_daw_normalization_support_case_history_event_check check(event in('created','note','state-changed','revoked','triaged','assigned','retention-extended','bundle-cleaned'));